export const defineAllThemes = (monaco) => {
  if (!monaco || !monaco.editor || monaco.editor._noctisThemesDefined) return;
  for (const t of themes) {
    monaco.editor.defineTheme(t.id, t.data);
  }
  monaco.editor._noctisThemesDefined = true;
};

export default {
  themes,
  defineAllThemes
};
